PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS video_models(id TEXT PRIMARY KEY,name TEXT NOT NULL,provider TEXT NOT NULL,version TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,created_at REAL NOT NULL);
CREATE TABLE IF NOT EXISTS video_challenges(id TEXT PRIMARY KEY,title TEXT NOT NULL,category TEXT NOT NULL CHECK(category IN ('text-to-video','image-to-video')),prompt TEXT NOT NULL,source_image TEXT,criterion TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published','withdrawn')),selection_policy TEXT NOT NULL DEFAULT 'first-successful',policy_deviation TEXT,created_at REAL NOT NULL);
CREATE TABLE IF NOT EXISTS video_runs(id TEXT PRIMARY KEY,challenge_id TEXT NOT NULL REFERENCES video_challenges(id),model_id TEXT NOT NULL REFERENCES video_models(id),platform TEXT NOT NULL,generated_at TEXT NOT NULL,settings TEXT NOT NULL DEFAULT '{}',attempt INTEGER NOT NULL CHECK(attempt>0),status TEXT NOT NULL CHECK(status IN ('planned','success','failed')),retry_reason TEXT,created_at REAL NOT NULL);
CREATE TABLE IF NOT EXISTS video_outputs(id TEXT PRIMARY KEY,run_id TEXT NOT NULL REFERENCES video_runs(id),video_path TEXT NOT NULL UNIQUE,thumbnail_path TEXT,duration REAL NOT NULL CHECK(duration>0),resolution TEXT NOT NULL,audio INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published','withdrawn')),created_at REAL NOT NULL);
CREATE TABLE IF NOT EXISTS video_pairs(id TEXT PRIMARY KEY,challenge_id TEXT NOT NULL REFERENCES video_challenges(id),output_1 TEXT NOT NULL REFERENCES video_outputs(id),output_2 TEXT NOT NULL REFERENCES video_outputs(id),status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published','withdrawn')),created_at REAL NOT NULL,CHECK(output_1<output_2),UNIQUE(output_1,output_2));
CREATE TABLE IF NOT EXISTS video_participants(id TEXT PRIMARY KEY,token_hash TEXT NOT NULL UNIQUE,created_at REAL NOT NULL);
CREATE TABLE IF NOT EXISTS video_sessions(id TEXT PRIMARY KEY,participant_id TEXT NOT NULL REFERENCES video_participants(id),pair_id TEXT NOT NULL REFERENCES video_pairs(id),a_output TEXT NOT NULL REFERENCES video_outputs(id),b_output TEXT NOT NULL REFERENCES video_outputs(id),created_at REAL NOT NULL);
CREATE TABLE IF NOT EXISTS video_votes(id TEXT PRIMARY KEY,participant_id TEXT NOT NULL REFERENCES video_participants(id),pair_id TEXT NOT NULL REFERENCES video_pairs(id),session_id TEXT REFERENCES video_sessions(id),a_output TEXT NOT NULL REFERENCES video_outputs(id),b_output TEXT NOT NULL REFERENCES video_outputs(id),choice TEXT NOT NULL CHECK(choice IN ('a','b','tie','both-bad','skip')),source TEXT NOT NULL CHECK(source IN ('public','team')),created_at REAL NOT NULL,invalidated_at REAL,invalid_reason TEXT,UNIQUE(participant_id,pair_id,source));
CREATE TABLE IF NOT EXISTS video_proposals(id TEXT PRIMARY KEY,participant_id TEXT NOT NULL REFERENCES video_participants(id),category TEXT NOT NULL,prompt TEXT NOT NULL,source_image TEXT,status TEXT NOT NULL DEFAULT 'pending',created_at REAL NOT NULL);
CREATE TABLE IF NOT EXISTS video_admins(user_id TEXT PRIMARY KEY REFERENCES users(id));
CREATE INDEX IF NOT EXISTS idx_video_pairs_status ON video_pairs(status,challenge_id);
CREATE INDEX IF NOT EXISTS idx_video_votes_pair ON video_votes(pair_id,source,invalidated_at);
CREATE TABLE IF NOT EXISTS video_vote_flags(id TEXT PRIMARY KEY,vote_id TEXT NOT NULL REFERENCES video_votes(id),admin_id TEXT NOT NULL REFERENCES users(id),reason TEXT NOT NULL,created_at REAL NOT NULL);
